  const half = () => 0.5;
  const almostOne = () => 0.999999;

  it('scales the doubling window by rng', () => {
    expect(backoffDelay(1, half)).toBe(1_000);
    expect(backoffDelay(2, half)).toBe(2_000);
    expect(backoffDelay(3, half)).toBe(4_000);
  });

  it('never exceeds the 15 minute cap', () => {
    expect(backoffDelay(20, almostOne)).toBeLessThan(15 * 60_000);
    expect(backoffDelay(20, almostOne)).toBeGreaterThan(15 * 60_000 - 5);
  });

  it('can be zero', () => {
    expect(backoffDelay(4, () => 0)).toBe(0);
  });
});

